const d = $input.first().json;

// ── Ejecutado mes actual ──────────────────────────────────────────────
const mesActual = d.anio_mes_actual;
const serviciosEjecutados = (d.ejecutado_por_servicio_by_month?.[mesActual] ?? []);
const totalEjecutado = serviciosEjecutados.reduce((s, r) => s + (r.monto || 0), 0);

// ── Forecast OTs abiertas (mes actual) ───────────────────────────────
const otsAbiertas = (d.ots_abiertas ?? []).filter(o => o.mes_id === mesActual);
const totalForecast = otsAbiertas.reduce((s, o) => s + (o.total_ot || 0), 0);

// ── Presupuesto ───────────────────────────────────────────────────────
const presupuesto = d.meta_default ?? 21000000;

// ── Totales ───────────────────────────────────────────────────────────
const totalProyectado = totalEjecutado + totalForecast;
const desviacion = presupuesto - totalProyectado;
const pctEjecutado = presupuesto > 0 ? ((totalEjecutado / presupuesto) * 100).toFixed(1) : '0.0';
const pctForecast  = presupuesto > 0 ? ((totalProyectado / presupuesto) * 100).toFixed(1) : '0.0';

// ── Helpers ──────────────────────────────────────────────────────────
const fmt = n => '$' + Math.round(n).toLocaleString('es-CO');
const fmtDes = n => {
  const abs = fmt(Math.abs(n));
  return n >= 0 ? `✅ ${abs} bajo presupuesto` : `🔴 ${abs} SOBRE presupuesto`;
};

// ── Líneas de servicios ejecutados (solo monto > 0) ──────────────────
const lineasServicios = serviciosEjecutados
  .filter(r => r.monto > 0)
  .map(r => `  • ${r.servicio}: ${fmt(r.monto)}`)
  .join('\n');

// ── Conteo OTs abiertas por servicio ─────────────────────────────────
const conteoAbiertas = {};
otsAbiertas.forEach(o => {
  conteoAbiertas[o.service_name] = (conteoAbiertas[o.service_name] || 0) + 1;
});
const lineasAbiertas = Object.entries(conteoAbiertas)
  .map(([svc, cnt]) => `  • ${svc}: ${cnt} OT${cnt !== 1 ? 's' : ''}`)
  .join('\n');

// ── Fecha corte ──────────────────────────────────────────────────────
const fechaCorte = d.fecha_corte ?? mesActual;
const [yy, mm, dd] = fechaCorte.split('-');
const fechaLabel = `${dd}/${mm}/${yy}`;

// ── ID Slack de la persona a etiquetar ──────────────────────────────
// Cómo encontrarlo: en Slack, click en el perfil de la persona → "..." → "Copiar ID de miembro"
const SLACK_USER_ID = 'U0703VCP42U';

// ── Mensaje final ─────────────────────────────────────────────────────
const texto = [
  `<@${SLACK_USER_ID}> buenos días 👋`,
  '',
  `📊 *OPEX Activación — ${d.mes_label_actual}*`,
  `📅 Datos al ${fechaLabel}`,
  '',
  `━━━━━━━━━━━━━━━━━━━━`,
  `💰 *Presupuesto mes:* ${fmt(presupuesto)}`,
  `✅ *Ejecutado:* ${fmt(totalEjecutado)} _(${pctEjecutado}% del presupuesto)_`,
  `🔮 *Forecast OTs abiertas:* ${fmt(totalForecast)}`,
  `📈 *Total proyectado:* ${fmt(totalProyectado)} _(${pctForecast}% del presupuesto)_`,
  `⚡ *Desviación:* ${fmtDes(desviacion)}`,
  `━━━━━━━━━━━━━━━━━━━━`,
  '',
  ...(lineasServicios ? ['*Ejecutado por servicio:*', lineasServicios, ''] : []),
  ...(lineasAbiertas ? [`*OTs abiertas (${otsAbiertas.length}):*`, lineasAbiertas, ''] : []),
  `_🔗 <https://hernanmanjarres-cmyk.github.io/dash_opex_act/|Ver dashboard completo →>_`
].join('\n');

return [{ json: { texto } }];
